<?php
$facets=is_array($facets??null)?$facets:['colors'=>[],'sizes'=>[],'min_price'=>0,'max_price'=>0];
$priceSuggestionMax=min(1000,max(20,(int)(ceil((float)($facets['max_price']??0)/5)*5)));
$priceRangeEndCents=(int)round($priceSuggestionMax*100);$activeMinCents=isset($filters['min_price'])?(int)round((float)$filters['min_price']*100):null;$activeMaxCents=isset($filters['max_price'])?(int)round((float)$filters['max_price']*100):null;
$categories=is_array($categories??null)?$categories:[];
$categoryChildren=[];$categoryById=[];foreach($categories as $categoryOption)$categoryById[(int)$categoryOption['id']]=$categoryOption;foreach($categories as $categoryOption){$id=(int)$categoryOption['id'];$parentId=(int)($categoryOption['parent_id']??0);if($parentId>0&&!isset($categoryById[$parentId]))$parentId=0;$categoryChildren[$parentId][]=$id;}
$orderedCategories=[];$seenCategories=[];$flattenCategories=function(int $parentId,int $depth=0)use(&$flattenCategories,&$orderedCategories,&$seenCategories,$categoryChildren,$categoryById):void{foreach($categoryChildren[$parentId]??[] as $id){if(isset($seenCategories[$id]))continue;$seenCategories[$id]=true;$option=$categoryById[$id];$option['_depth']=min(6,$depth);$orderedCategories[]=$option;$flattenCategories($id,$depth+1);}};$flattenCategories(0);foreach($categories as $categoryOption)if(!isset($seenCategories[(int)$categoryOption['id']])){$categoryOption['_depth']=0;$orderedCategories[]=$categoryOption;}$categories=$orderedCategories;
$selectedCategoryIds=array_map('intval',$filters['categories']??[]);$expandedCategoryIds=[];foreach($selectedCategoryIds as $selectedId){$cursor=$categoryById[$selectedId]??null;while($cursor&&isset($cursor['parent_id'])&&$cursor['parent_id']!==null){$parentId=(int)$cursor['parent_id'];$expandedCategoryIds[$parentId]=true;$cursor=$categoryById[$parentId]??null;}}
$renderCategoryTree=function(int $parentId,int $depth=0)use(&$renderCategoryTree,$categoryChildren,$categoryById,$selectedCategoryIds,$expandedCategoryIds,$view):void{foreach($categoryChildren[$parentId]??[] as $id){$item=$categoryById[$id]??null;if(!$item)continue;$children=$categoryChildren[$id]??[];$hasChildren=(bool)$children;$expanded=isset($expandedCategoryIds[$id]);$panelId='catalog-category-children-'.$id;?><div class="catalog-category-node" style="--category-depth:<?= min(6,$depth) ?>"><div class="catalog-category-row"><label class="catalog-filter-option"><input type="checkbox" name="category[]" value="<?= $id ?>" <?= in_array($id,$selectedCategoryIds,true)?'checked':'' ?>><span><?= $view->e($item['name']) ?></span></label><?php if($hasChildren): ?><button class="catalog-category-toggle<?= $expanded?' is-expanded':'' ?>" type="button" data-category-name="<?= $view->e($item['name']) ?>" aria-controls="<?= $panelId ?>" aria-expanded="<?= $expanded?'true':'false' ?>" aria-label="<?= $view->e(($expanded?'Скрий':'Покажи').' подкатегориите на '.$item['name']) ?>"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5 7.5 5 5 5-5"/></svg></button><?php endif; ?></div><?php if($hasChildren): ?><div class="catalog-category-children<?= $expanded?' is-expanded':'' ?>" id="<?= $panelId ?>" <?= $expanded?'':'inert' ?>><div class="catalog-category-children-inner"><?php $renderCategoryTree($id,$depth+1); ?></div></div><?php endif; ?></div><?php }};
?>
<aside class="catalog-sidebar" id="catalog-filters" aria-label="Филтри на продуктите">
  <form method="get" id="catalog-filter-form" class="catalog-filter-form" data-live-catalog-filters>
    <div class="catalog-filter-drawer-header"><h2>Филтри</h2><?php $closeButtonLabel="Затвори филтрите"; $closeButtonClass="catalog-sidebar-close"; $closeButtonAttributes=["data-catalog-filter-close"=>true]; include __DIR__."/close-button.php"; ?></div>
    <input type="hidden" name="columns" value="<?= (int)($filters['columns']??4) ?>">
    <div class="catalog-filter-section">
      <h3>Цена (€)</h3>
      <div class="catalog-price-fields"><label><span>От</span><input type="number" name="min_price" min="0" step="0.01" placeholder="<?= $view->e(number_format((float)($facets['min_price']??0),2,'.','')) ?>" value="<?= $view->e($filters['min_price']??'') ?>"></label><label><span>До</span><input type="number" name="max_price" min="0" step="0.01" placeholder="<?= $view->e(number_format((float)($facets['max_price']??0),2,'.','')) ?>" value="<?= $view->e($filters['max_price']??'') ?>"></label></div>
      <div class="catalog-filter-options catalog-price-presets" aria-label="Предложени ценови диапазони"><?php for($rangeMinCents=0;$rangeMinCents<$priceRangeEndCents;$rangeMinCents+=500): $rangeMaxCents=min($rangeMinCents+499,$priceRangeEndCents); $rangeLabelMaxCents=min($rangeMinCents+500,$priceRangeEndCents); $rangeMin=$rangeMinCents/100; $rangeMax=$rangeMaxCents/100; $rangeLabelMax=$rangeLabelMaxCents/100; $rangeChecked=$activeMinCents===$rangeMinCents&&$activeMaxCents===$rangeMaxCents; ?><label class="catalog-filter-option"><input type="checkbox" data-catalog-price-range data-min-price="<?= number_format($rangeMin,2,'.','') ?>" data-max-price="<?= number_format($rangeMax,2,'.','') ?>" <?= $rangeChecked?'checked':'' ?>><span><?= $rangeMinCents===0?'До '.number_format($rangeLabelMax,0,',',' ').' €':'От '.number_format($rangeMin,0,',',' ').' до '.number_format($rangeLabelMax,0,',',' ').' €' ?></span></label><?php endfor; ?></div>
    </div>
    <?php if(!empty($facets['colors'])): ?><fieldset class="catalog-filter-section"><legend>Цвят</legend><div class="catalog-filter-options"><?php foreach($facets['colors'] as $color): ?><label class="catalog-filter-option"><input type="checkbox" name="color[]" value="<?= $view->e($color['label']) ?>" <?= in_array($color['label'],$filters['colors']??[],true)?'checked':'' ?>><span class="catalog-filter-swatch" style="--filter-color:<?= $view->e($color['hex']?:'#ead0d6') ?>"></span><span><?= $view->e($color['label']) ?></span></label><?php endforeach; ?></div></fieldset><?php endif; ?>
    <?php if(!empty($facets['sizes'])): ?><fieldset class="catalog-filter-section"><legend>Размер</legend><div class="catalog-filter-options catalog-filter-options-compact"><?php foreach($facets['sizes'] as $size): ?><label class="catalog-filter-option"><input type="checkbox" name="size[]" value="<?= $view->e($size) ?>" <?= in_array($size,$filters['sizes']??[],true)?'checked':'' ?>><span><?= $view->e($size) ?></span></label><?php endforeach; ?></div></fieldset><?php endif; ?>
    <fieldset class="catalog-filter-section"><legend>Категории</legend><div class="catalog-category-tree"><?php $renderCategoryTree(0); ?></div></fieldset>
    <div class="catalog-special-filters"><label class="catalog-filter-option"><input type="checkbox" name="in_stock" value="1" <?= !empty($filters['in_stock'])?'checked':'' ?>><span>Само налични</span></label><label class="catalog-filter-option"><input type="checkbox" name="on_sale" value="1" <?= !empty($filters['on_sale'])?'checked':'' ?>><span>Само промоции</span></label></div>
  </form>
</aside>
<style>
.catalog-layout{display:grid;grid-template-columns:330px minmax(0,1fr);gap:20px;align-items:start}.catalog-layout.filters-collapsed{grid-template-columns:minmax(0,1fr)}.catalog-results{min-width:0}.catalog-sidebar{position:sticky;top:18px;background:transparent;border:0;border-radius:0;padding:0}.catalog-sidebar.is-collapsed{display:none}.catalog-filter-section{display:grid;gap:8px;margin:0 0 14px;padding:0 0 13px;border:0;border-bottom:1px solid var(--line)}.catalog-filter-section h3,.catalog-filter-section legend{margin:0 0 10px;padding:0;font-size:1.08rem;font-weight:400}.catalog-price-fields{display:grid;grid-template-columns:1fr 1fr;gap:8px}.catalog-price-fields label{display:grid;gap:5px;color:var(--muted);font-size:.88rem}.catalog-price-fields input,.catalog-filter-section select{width:100%;min-width:0;padding:10px 11px;border:1px solid var(--line);border-radius:9px;background:#fff;color:var(--ink)}.catalog-filter-options{display:grid;gap:8px}.catalog-filter-options-compact{grid-template-columns:repeat(3,minmax(0,1fr))}.catalog-price-presets{grid-template-columns:1fr 1fr;max-height:none;overflow:visible;padding-right:0}.catalog-filter-option{display:flex;align-items:center;gap:9px;min-width:0;color:#544a49;font-size:.96rem;cursor:pointer}.catalog-filter-option input{width:17px;height:17px;flex:none;accent-color:var(--accent)}.catalog-filter-swatch{width:19px;height:19px;flex:none;border:1px solid #d5c8c8;border-radius:50%;background:var(--filter-color)}.catalog-category-tree{display:grid;gap:5px}.catalog-category-node{min-width:0}.catalog-category-row{display:flex;align-items:center;justify-content:space-between;gap:5px}.catalog-category-row>.catalog-filter-option{flex:1;min-width:0}.catalog-category-toggle{display:grid;width:32px;height:32px;flex:none;place-items:center;padding:0;border:1px solid transparent;border-radius:8px;background:transparent;color:#756b66;cursor:pointer;transition:background .18s,color .18s}.catalog-category-toggle:hover{background:#fff1f4;color:var(--accent-dark)}.catalog-category-toggle svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;transition:transform .24s ease}.catalog-category-toggle.is-expanded svg{transform:rotate(180deg)}.catalog-category-children{display:grid;grid-template-rows:0fr;opacity:0;transition:grid-template-rows .28s ease,opacity .22s ease}.catalog-category-children.is-expanded{grid-template-rows:1fr;opacity:1}.catalog-category-children-inner{min-height:0;overflow:hidden}.catalog-category-children-inner>.catalog-category-node{margin-left:17px;padding-left:10px;border-left:1px solid #f0dce1}.catalog-special-filters{display:grid;gap:10px;margin:0 0 18px}
.catalog-filter-drawer-header{display:none}
@media(max-width:760px){.catalog-layout,.catalog-layout.filters-collapsed{grid-template-columns:1fr;gap:12px}.catalog-sidebar{position:static;max-height:none}}
@media(max-width:1199px){.catalog-layout,.catalog-layout.filters-collapsed{grid-template-columns:minmax(0,1fr);gap:12px}.catalog-sidebar{position:fixed;z-index:1300;inset:0;display:flex;align-items:stretch;max-height:none;padding:0;background:#17131a99;visibility:hidden;pointer-events:none;opacity:0;transition:opacity .24s ease,visibility 0s linear .28s}.catalog-sidebar::before{content:"";position:absolute;inset:0;backdrop-filter:blur(2px)}.catalog-sidebar.is-open{visibility:visible;pointer-events:auto;opacity:1;transition-delay:0s}.catalog-sidebar.is-collapsed{display:flex}.catalog-filter-form{position:relative;z-index:1;width:min(420px,88vw);height:100%;overflow:auto;overscroll-behavior:contain;padding:0 22px max(22px,env(safe-area-inset-bottom));background:#fff;box-shadow:18px 0 50px #1b121d30;transform:translateX(-105%);transition:transform .28s cubic-bezier(.22,.75,.25,1)}.catalog-sidebar.is-open .catalog-filter-form{transform:translateX(0)}.catalog-filter-drawer-header{position:sticky;top:0;z-index:5;display:flex;align-items:center;justify-content:space-between;gap:16px;margin:0 -22px 18px;padding:15px 22px;background:linear-gradient(180deg,#fff 0%,#fffdfc 100%);border-bottom:1px solid #eadfd9;box-shadow:0 5px 15px #32212b0a}.catalog-filter-drawer-header h2{margin:0;padding:6px 12px;border:1px solid #f0e2e3;border-radius:9px;background:#fff8f8;color:var(--ink);font-size:1.16rem;font-weight:500;line-height:1.35}.catalog-sidebar-close{flex:0 0 42px;width:42px;height:42px;display:grid;place-items:center;padding:0;border:1px solid #eee2e1;border-radius:12px;background:#fff;color:#52474a;cursor:pointer;transition:background .18s,border-color .18s,transform .18s}.catalog-sidebar-close svg{display:block;width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round}.catalog-sidebar-close:hover{border-color:#e3c4ca;background:#fff2f3;color:var(--accent-dark);transform:rotate(5deg)}}
@media(min-width:1200px){.catalog-layout{grid-template-columns:330px minmax(0,1fr);transition:grid-template-columns .32s cubic-bezier(.22,.75,.25,1)}.catalog-layout.filters-collapsed{grid-template-columns:0 minmax(0,1fr);gap:0}.catalog-sidebar{min-width:0;overflow:hidden;opacity:1;transform:translateX(0);transition:opacity .2s ease,transform .32s cubic-bezier(.22,.75,.25,1),visibility 0s}.catalog-sidebar.is-collapsed{display:block;visibility:hidden;opacity:0;transform:translateX(-18px);pointer-events:none;transition:opacity .2s ease,transform .32s cubic-bezier(.22,.75,.25,1),visibility 0s linear .32s}}
@media(prefers-reduced-motion:reduce){.catalog-sidebar,.catalog-filter-form,.catalog-layout{transition:none!important}}
</style>
<script>
(()=>{if(window.__giftchetaLiveCatalogFilters)return;window.__giftchetaLiveCatalogFilters=true;window.addEventListener('giftcheta:catalog-updated',()=>{const count=document.querySelector('.catalog-result-count')?.textContent.match(/\d+/)?.[0],badge=document.querySelector('[data-catalog-heading-count]');if(count&&badge)badge.textContent=' ('+count+')'});let controller=null,timer=null,appendController=null;const find=selector=>document.querySelector(selector),drawerMode=()=>window.matchMedia('(max-width: 1199px)').matches;let drawerFocus=null;function setDrawer(open){const sidebar=find('#catalog-filters'),toggle=find('[data-catalog-filter-toggle]');if(!sidebar)return;sidebar.classList.toggle('is-open',open);sidebar.setAttribute('aria-hidden',String(!open));if(drawerMode()){sidebar.setAttribute('role','dialog');sidebar.setAttribute('aria-modal','true')}if(toggle)toggle.setAttribute('aria-expanded',String(open));if(open){drawerFocus=document.activeElement;document.documentElement.style.overflow='hidden';sidebar.querySelector('[data-catalog-filter-close]')?.focus()}else{document.documentElement.style.overflow='';if(drawerFocus&&drawerFocus.isConnected)drawerFocus.focus();drawerFocus=null}}function syncDrawerMode(){const sidebar=find('#catalog-filters'),toggle=find('[data-catalog-filter-toggle]');if(!sidebar||!toggle)return;if(drawerMode()){sidebar.classList.remove('is-open');sidebar.classList.remove('is-collapsed');sidebar.setAttribute('aria-hidden','true');toggle.setAttribute('aria-expanded','false');document.documentElement.style.overflow=''}else{sidebar.classList.remove('is-open');sidebar.removeAttribute('aria-hidden');sidebar.removeAttribute('role');sidebar.removeAttribute('aria-modal');toggle.setAttribute('aria-expanded',String(!sidebar.classList.contains('is-collapsed')));document.documentElement.style.overflow=''}}window.addEventListener('resize',syncDrawerMode);window.addEventListener('keydown',event=>{const sidebar=find('#catalog-filters');if(!drawerMode()||!sidebar?.classList.contains('is-open'))return;if(event.key==='Escape'){event.preventDefault();setDrawer(false);return}if(event.key==='Tab'){const focusable=[...sidebar.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),a[href]')],first=focusable[0],last=focusable[focusable.length-1];if(!first)return;if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',syncDrawerMode,{once:true});else syncDrawerMode();function syncInfiniteScroll(){if(!('IntersectionObserver'in window))return;const nav=find('.catalog-results [data-infinite-pagination]');if(!nav||!nav.querySelector('a[rel="next"]'))return;if(window.__giftchetaInfiniteObserver)window.__giftchetaInfiniteObserver.disconnect();window.__giftchetaInfiniteObserver=new IntersectionObserver(entries=>{if(entries.some(entry=>entry.isIntersecting)){const next=find('.catalog-results [data-infinite-pagination] a[rel="next"]');if(next&&!appendController)load(next.pathname+next.search,{append:true})}},{rootMargin:'700px 0px'});window.__giftchetaInfiniteObserver.observe(nav)}async function load(url,{push=true,append=false}={}){clearTimeout(timer);const results=find('.catalog-results');if(!results)return;if(!append){controller?.abort();appendController?.abort();controller=new AbortController()}else{appendController?.abort();appendController=new AbortController()}const activeController=append?appendController:controller;results.classList.add(append?'is-appending':'is-loading');results.setAttribute('aria-busy','true');const grid=results.querySelector('.product-grid');if(append&&grid){const columnCount=Number(grid.dataset.columns)||4,skeletonCount=Math.max(2,columnCount*2);for(let index=0;index<skeletonCount;index++){const card=document.createElement('article');card.className='catalog-skeleton-card catalog-appended-skeleton';const media=document.createElement('div');media.className='catalog-skeleton-media';const body=document.createElement('div');body.className='catalog-skeleton-body';for(const className of ['catalog-skeleton-line is-title','catalog-skeleton-line','catalog-skeleton-line is-short','catalog-skeleton-line is-price','catalog-skeleton-action']){const block=document.createElement('span');block.className=className;body.append(block)}card.append(media,body);grid.append(card)}}try{const response=await fetch(url,{signal:activeController.signal,headers:{'X-Requested-With':'XMLHttpRequest','Accept':'text/html'}});if(!response.ok)throw new Error('Catalog request failed');const html=await response.text(),doc=new DOMParser().parseFromString(html,'text/html'),nextResults=doc.querySelector('.catalog-results');if(!nextResults)throw new Error('Catalog results missing');results.querySelectorAll('style').forEach(style=>document.head.append(style.cloneNode(true)));nextResults.querySelectorAll('style,script').forEach(asset=>asset.remove());if(append){const targetGrid=results.querySelector('.product-grid'),incomingGrid=nextResults.querySelector('.product-grid');results.querySelectorAll('.catalog-appended-skeleton').forEach(card=>card.remove());if(targetGrid&&incomingGrid)targetGrid.append(...incomingGrid.children);const oldPagination=results.querySelector('[data-infinite-pagination]'),newPagination=nextResults.querySelector('[data-infinite-pagination]');if(oldPagination)oldPagination.replaceWith(newPagination||document.createDocumentFragment());const count=nextResults.querySelector('.catalog-result-count'),currentCount=results.querySelector('.catalog-result-count');if(count&&currentCount)currentCount.textContent=count.textContent}else{results.replaceWith(nextResults)}if(push)history.pushState({},'',url);window.dispatchEvent(new CustomEvent('giftcheta:catalog-updated'));}catch(error){if(append)results.querySelectorAll('.catalog-appended-skeleton').forEach(card=>card.remove());if(error.name!=='AbortError')window.location.assign(url)}finally{if((append?appendController:controller)===activeController){const current=find('.catalog-results');current?.classList.remove(append?'is-appending':'is-loading');current?.removeAttribute('aria-busy');if(append){appendController=null;syncInfiniteScroll()}else syncInfiniteScroll()}}}function formUrl(form){const url=new URL(form.action||location.href,location.origin);url.search=new URLSearchParams(new FormData(form)).toString();url.searchParams.delete('page');return url.pathname+url.search}document.addEventListener('click',event=>{const categoryToggle=event.target.closest('.catalog-category-toggle');if(categoryToggle){const panel=document.getElementById(categoryToggle.getAttribute('aria-controls'));if(!panel)return;const expanded=categoryToggle.getAttribute('aria-expanded')==='true';categoryToggle.setAttribute('aria-expanded',String(!expanded));categoryToggle.classList.toggle('is-expanded',!expanded);categoryToggle.setAttribute('aria-label',(expanded?'Покажи':'Скрий')+' подкатегориите на '+categoryToggle.dataset.categoryName);if(expanded){panel.classList.remove('is-expanded');window.setTimeout(()=>{if(categoryToggle.getAttribute('aria-expanded')==='false')panel.setAttribute('inert','')},300)}else{panel.removeAttribute('inert');panel.classList.add('is-expanded')}return}const toggle=event.target.closest('[data-catalog-filter-toggle]');if(toggle){const sidebar=find('#catalog-filters'),layout=sidebar?.closest('.catalog-layout');if(!sidebar||!layout)return;toggle.setAttribute('aria-controls','catalog-filters');if(drawerMode()){setDrawer(true)}else{const collapsed=sidebar.classList.toggle('is-collapsed');layout.classList.toggle('filters-collapsed',collapsed);toggle.setAttribute('aria-expanded',String(!collapsed))}return}if(event.target.closest('[data-catalog-filter-close]')){setDrawer(false);return}if(drawerMode()&&event.target===find('#catalog-filters')){setDrawer(false);return}const clear=event.target.closest('.catalog-toolbar-clear');if(clear){const url=new URL(clear.href,location.origin);if(url.origin===location.origin){event.preventDefault();const form=find('#catalog-filter-form');form?.querySelectorAll('input[type="checkbox"],input[type="number"]').forEach(input=>{if(input.type==='checkbox')input.checked=false;else input.value=''});const sort=find('#catalog-sort');if(sort)sort.value='latest';const columns=form?.querySelector('input[name="columns"]')?.value;if(columns)url.searchParams.set('columns',columns);load(url.pathname+url.search)}return}const link=event.target.closest('.catalog-results .pagination a');if(link&&link.origin===location.origin){event.preventDefault();load(link.pathname+link.search)}});document.addEventListener('submit',event=>{const form=event.target.closest('[data-live-catalog-filters]');if(!form)return;event.preventDefault();load(formUrl(form))});document.addEventListener('change',event=>{const range=event.target.closest('[data-catalog-price-range]');if(!range)return;const form=range.closest('[data-live-catalog-filters]');if(!form)return;event.stopImmediatePropagation();form.querySelectorAll('[data-catalog-price-range]').forEach(option=>{if(option!==range)option.checked=false});const min=form.querySelector('[name="min_price"]'),max=form.querySelector('[name="max_price"]');if(min)min.value=range.checked?range.dataset.minPrice:'';if(max)max.value=range.checked?range.dataset.maxPrice:'';load(formUrl(form))});document.addEventListener('change',event=>{const form=event.target.matches('#catalog-sort')?document.getElementById('catalog-filter-form'):event.target.closest('[data-live-catalog-filters]');if(!form)return;if(event.target.matches('input[type=checkbox], select'))load(formUrl(form))});document.addEventListener('input',event=>{if(!event.target.matches('[data-live-catalog-filters] input[name="min_price"],[data-live-catalog-filters] input[name="max_price"]'))return;event.target.closest('[data-live-catalog-filters]')?.querySelectorAll('[data-catalog-price-range]').forEach(option=>option.checked=false)});document.addEventListener('input',event=>{if(!event.target.matches('[data-live-catalog-filters] input[type=number]'))return;clearTimeout(timer);timer=setTimeout(()=>load(formUrl(event.target.form)),450)});window.addEventListener('popstate',()=>{load(location.pathname+location.search,{push:false});syncInfiniteScroll()});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',syncInfiniteScroll,{once:true});else syncInfiniteScroll()})();
</script>
